  S: B.stairs("spruce", "east", "bottom"),
  b: ["barrel", { facing: "up", open: "false" }],
  C: "cauldron",
  L: ["lantern", { hanging: "false" }],
};

// y3: floor-level furniture.
const FLOOR = [
  "..", // z9  open end
  ".b", // z10 barrel, east column
  "S.", // z11 bench against the west wall
