  "..", // z13
  ".C", // z14 cauldron, east column
  "..", // z15 open end
];

// y4: the lantern stands on the barrel's top face.
const ABOVE = [
  "..",
  ".L",
  "..",
  "..",
  "..",
  "..",
  "..",
];

export function build(g) {
  layers(g, [5, 3, 9], LEGEND, [FLOOR, ABOVE]);
}

